const agora = new Date();
const ano = agora.getUTCFullYear();
const mes = agora.getUTCMonth();
const dia = agora.getUTCDate();
const primeiroMesAlvo = new Date(Date.UTC(ano, mes - 15, 1));
const ultimoDiaMesAlvo = new Date(Date.UTC(
  primeiroMesAlvo.getUTCFullYear(),
  primeiroMesAlvo.getUTCMonth() + 1,
  0,
)).getUTCDate();
const limite = new Date(Date.UTC(
  primeiroMesAlvo.getUTCFullYear(),
  primeiroMesAlvo.getUTCMonth(),
  Math.min(dia, ultimoDiaMesAlvo),
));

return [{ json: {
  meses_retencao: 15,
  data_limite_exclusiva: limite.toISOString().slice(0, 10),
  executado_em: agora.toISOString(),
} }];

const cfg = $('Configurar retenção de 15 meses').first().json;
const limite = cfg.data_limite_exclusiva;
const antigos = $input.all()
  .map((item) => item.json)
  .filter((linha) => {
    const data = String(linha.data ?? '').slice(0, 10);
    return /^\d{4}-\d{2}-\d{2}$/.test(data) && Boolean(linha.chave) && data < limite;
  })
  .sort((a, b) => String(a.data).localeCompare(String(b.data)) || String(a.chave).localeCompare(String(b.chave)));

if (!antigos.length) return [{ json: {
  quantidade: 0,
  sem_registros_expirados: true,
  data_limite_exclusiva: limite,
  aviso: `Nenhum registro anterior a ${limite}. Nada foi arquivado ou excluído.`,
} }];

const colunas = ['id', 'chave', 'instagram_id', 'usuario', 'cliente', 'data', 'saldo_dia', 'createdAt', 'updatedAt'];
const csv = (valor) => {
  const texto = String(valor ?? '');
  return /[",\n\r]/.test(texto) ? `"${texto.replace(/"/g, '""')}"` : texto;
};
const linhas = [
  colunas.join(','),
  ...antigos.map((linha) => colunas.map((coluna) => csv(linha[coluna])).join(',')),
];

return [{ json: {
  csv: `\uFEFF${linhas.join('\n')}\n`,
  nome_arquivo: `Arquivo seguidores Instagram - anteriores a ${limite}.csv`,
  data_limite_exclusiva: limite,
  quantidade: antigos.length,
  chaves: antigos.map((linha) => String(linha.chave)),
} }];

const arquivo = $('Preparar arquivo de retenção').first().json;
if (!Array.isArray(arquivo.chaves) || !arquivo.chaves.length) return [];

return arquivo.chaves.map((chave) => ({ json: {
  chave,
  arquivo: arquivo.nome_arquivo,
  quantidade_total: arquivo.quantidade,
  data_limite_exclusiva: arquivo.data_limite_exclusiva,
} }));

const arquivo = $('Preparar arquivo de retenção').first().json;
return [{ json: {
  status: 'RETENCAO_CONCLUIDA',
  arquivo: arquivo.nome_arquivo,
  registros_arquivados_e_excluidos: arquivo.quantidade,
  anteriores_a: arquivo.data_limite_exclusiva,
} }];

const agora = new Date();
const partes = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(agora).filter((p) => p.type !== 'literal').map((p) => [p.type, p.value]));

const hojeUtc = Date.UTC(Number(partes.year), Number(partes.month) - 1, Number(partes.day));
const DIA = 86400000;
const iso = (ms) => new Date(ms).toISOString().slice(0, 10);

return [{ json: {
  graph_version: 'v25.0',
  business_id: '799154829958463',
  since_date: iso(hojeUtc - 30 * DIA),
  until_date: iso(hojeUtc),
  ultima_data_incluida: iso(hojeUtc - DIA),
  dias_recuperacao: 30,
  executado_em: agora.toISOString(),
} }];

const ler = (nome) => {
  try {
    return $(nome).first().json.data ?? [];
  } catch {
    return [];
  }
};

const paginas = [
  ...ler('Listar paginas proprias2'),
  ...ler('Listar paginas dos clientes2'),
];

const unicas = new Map();

for (const pagina of paginas) {
  const instagram = pagina.instagram_business_account;

  if (!instagram?.id) continue;

  unicas.set(String(instagram.id), {
    instagram_id: String(instagram.id),
    usuario: instagram.username ?? '',
    cliente:
      instagram.name ||
      pagina.name ||
      instagram.username ||
      String(instagram.id),
    pagina_id: String(pagina.id ?? ''),
  });
}

if (!unicas.size) {
  throw new Error(
    'Nenhuma conta do Instagram acessível foi encontrada no portfólio LEME.'
  );
}

return [...unicas.values()].map((json) => ({ json }));

const conta = $('Loop contas1').first().json;
const cfg = $('Configuração diária1').first().json;
const resposta = $input.first().json ?? {};
const metrica = Array.isArray(resposta.data)
  ? resposta.data.find((item) => item.name === 'follower_count')
  : null;

if (!metrica || !Array.isArray(metrica.values)) {
  return [{ json: {
    gravar: false,
    instagram_id: String(conta.instagram_id),
    usuario: String(conta.usuario ?? ''),
    cliente: String(conta.cliente ?? conta.usuario ?? conta.instagram_id),
    aviso: `A Meta não devolveu follower_count para @${conta.usuario || conta.instagram_id}. Nenhum zero foi gravado.`,
  } }];
}

const inicio = new Date(`${cfg.since_date}T00:00:00.000Z`).getTime();
const fim = new Date(`${cfg.until_date}T00:00:00.000Z`).getTime();
const valores = new Map();

for (const item of metrica.values) {
  const data = String(item.end_time ?? '').slice(0, 10);
  const instante = new Date(`${data}T00:00:00.000Z`).getTime();
  const valor = Number(item.value);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) continue;
  if (!Number.isFinite(instante) || instante < inicio || instante >= fim) continue;
  if (!Number.isFinite(valor) || valor < 0) continue;
  valores.set(data, Math.trunc(valor));
}

if (!valores.size) {
  return [{ json: {
    gravar: false,
    instagram_id: String(conta.instagram_id),
    usuario: String(conta.usuario ?? ''),
    cliente: String(conta.cliente ?? conta.usuario ?? conta.instagram_id),
    aviso: `A Meta não devolveu nenhum dia válido de follower_count para @${conta.usuario || conta.instagram_id}.`,
  } }];
}

return [...valores.entries()]
  .sort((a, b) => a[0].localeCompare(b[0]))
  .map(([data, saldoDia]) => ({ json: {
    gravar: true,
    chave: `${conta.instagram_id}_${data}`,
    instagram_id: String(conta.instagram_id),
    usuario: String(conta.usuario ?? ''),
    cliente: String(conta.cliente ?? conta.usuario ?? conta.instagram_id),
    data,
    saldo_dia: saldoDia,
  } }));

const cfg = $('Configuração diária1').first().json;
return [{ json: {
  status: 'COLETA_DIARIA_CONCLUIDA',
  periodo_consultado: `${cfg.since_date} a ${cfg.ultima_data_incluida}`,
  contas_processadas: $('Consolidar contas Instagram1').all().length,
  observacao: 'Somente datas efetivamente devolvidas pela Meta foram gravadas; nenhum dia ausente foi preenchido com zero.',
} }];

const blocos = $('Preparar blocos cliques').all();
const respostas = $input.all();
let total = 0;
let encontradas = 0;
for (const resposta of respostas) {
  const metrica = (resposta.json.data ?? []).find((d) => d.name === 'website_clicks');
  const valor = Number(metrica?.total_value?.value);
  if (Number.isFinite(valor)) { total += valor; encontradas++; }
}
const base = { ...blocos[0].json };
delete base.meta_since;
delete base.meta_until;
delete base.meta_since_date;
delete base.meta_until_date;
return [{ json: { ...base, cliques_total: total, cliques_total_valido: respostas.length === blocos.length && encontradas === blocos.length }}];

const DIA = 86400000;
const base = $input.first().json;
const inicio = new Date(`${base.since_date}T00:00:00.000Z`);
const fim = new Date(`${base.until_date}T00:00:00.000Z`);
const saida = [];
let cursor = inicio.getTime();
while (cursor < fim.getTime()) {
  const proximo = Math.min(cursor + 30 * DIA, fim.getTime());
  saida.push({ json: {
    ...base,
    meta_since: Math.floor(cursor / 1000),
    meta_until: Math.floor((proximo - 1000) / 1000),
