const blocos = $('Preparar blocos alcance diário').all();
const respostas = $input.all();
if (!blocos.length || respostas.length !== blocos.length) {
  throw new Error('As respostas de alcance diário estão incompletas.');
}

const porFim = new Map();
let blocosValidos = 0;
for (const resposta of respostas) {
  const metrica = (resposta.json.data ?? []).find((d) => d.name === 'reach');
  if (!metrica || !Array.isArray(metrica.values)) continue;
  blocosValidos++;
  for (const valor of metrica.values) {
    if (!valor.end_time || !Number.isFinite(Number(valor.value))) continue;
    porFim.set(String(valor.end_time), Number(valor.value));
  }
}

const serie = [...porFim.entries()]
  .sort((a, b) => new Date(a[0]) - new Date(b[0]))
  .map(([endTime, value]) => ({
    end_time: endTime,
    label: new Date(endTime).toLocaleDateString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      timeZone: 'UTC',
    }),
    value,
  }));

const base = { ...blocos[0].json };
delete base.meta_since;
delete base.meta_until;
delete base.meta_since_date;
delete base.meta_until_date;
delete base.periodo_parte;
const inicio = new Date(`${base.since_date}T00:00:00.000Z`).getTime();
const fim = new Date(`${base.until_date}T00:00:00.000Z`).getTime();
const esperado = Math.round((fim - inicio) / 86400000);

return [{ json: {
  ...base,
  alcance_diario_custom: serie,
  alcance_diario_valido:
    blocosValidos === blocos.length &&
    Number.isFinite(esperado) &&
    serie.length === esperado,
} }];

