const base = $('Preparar período alcance total').first().json;
const metrica = ($input.first().json.data ?? []).find((d) => d.name === 'reach');
const valor = Number(metrica?.total_value?.value);
return [{ json: {
  ...base,
  alcance_total: Number.isFinite(valor) ? valor : null,
