}}];

const DIA = 86400000;
const base = $input.first().json;
const inicio = new Date(`${base.since_date}T00:00:00.000Z`);
const fim = new Date(`${base.until_date}T00:00:00.000Z`);
const dias = Math.round((fim.getTime() - inicio.getTime()) / DIA);

// Alcance é único e não pode ser somado entre blocos. Em meses de 31 dias,
// a API pública da Meta só permite o total dos últimos 30 dias do mês.
const alcanceInicio = dias > 30 ? new Date(fim.getTime() - 30 * DIA) : inicio;
return [{ json: {
  ...base,
  alcance_since: Math.floor(alcanceInicio.getTime() / 1000),
  alcance_until: Math.floor((fim.getTime() - 1000) / 1000),
  alcance_limitado_30_dias: dias > 30,
  alcance_periodo: `${String(alcanceInicio.getUTCDate()).padStart(2, '0')}/${String(alcanceInicio.getUTCMonth()+1).padStart(2, '0')} a ${String(new Date(fim.getTime()-DIA).getUTCDate()).padStart(2, '0')}/${String(new Date(fim.getTime()-DIA).getUTCMonth()+1).padStart(2, '0')}`,
}}];

const blocos = $('Dividir período em blocos de 30 dias').all();
const respostas = $input.all();
if (!blocos.length || respostas.length !== blocos.length) {
  throw new Error('As respostas de visualizações não correspondem aos blocos consultados.');
}

let total = 0;
let metricasEncontradas = 0;
for (const resposta of respostas) {
  const metrica = (resposta.json.data ?? []).find((d) => d.name === 'views');
  if (metrica && Number.isFinite(Number(metrica.total_value?.value))) {
    total += Number(metrica.total_value.value);
    metricasEncontradas++;
  }
}

const base = { ...blocos[0].json };
delete base.meta_since;
delete base.meta_until;
delete base.meta_since_date;
delete base.meta_until_date;
delete base.periodo_parte;
return [{ json: {
  ...base,
  views_total: total,
  views_total_valido: metricasEncontradas === blocos.length,
  views_blocos_consultados: blocos.length,
}}];

const DIA = 86400000;
const cfg = $('Configuração').first().json;
const cliente = $('Loop clientes').item.json;
const pastaMes = $input.first().json;
const inicio = new Date(`${cliente.since_date || cfg.since_date}T00:00:00.000Z`);
const fim = new Date(`${cliente.until_date || cfg.until_date}T00:00:00.000Z`);

if (!pastaMes?.id) throw new Error(`Pasta mensal não encontrada para ${cliente.nome_cliente}.`);
if (isNaN(inicio.getTime()) || isNaN(fim.getTime()) || inicio >= fim) {
  throw new Error(`Período inválido para ${cliente.nome_cliente}.`);
}

const saida = [];
let cursor = inicio.getTime();
let parte = 1;
while (cursor < fim.getTime()) {
  const proximo = Math.min(cursor + 30 * DIA, fim.getTime());
  saida.push({ json: {
    ...cliente,
    folder_mes_id: String(pastaMes.id),
    meta_since: Math.floor(cursor / 1000),
    meta_until: Math.floor((proximo - 1000) / 1000),
    meta_since_date: new Date(cursor).toISOString().slice(0, 10),
    meta_until_date: new Date(proximo - DIA).toISOString().slice(0, 10),
    periodo_parte: parte,
  }});
  cursor = proximo;
  parte++;
}
return saida;

const cliente = $input.first().json;
const numero = (v) => Number.isFinite(Number(v)) ? Number(v) : 0;
const formatar = (n) => n >= 1000000
  ? `${(n / 1000000).toFixed(1).replace('.', ',')} mi`
  : n >= 1000
    ? `${(n / 1000).toFixed(1).replace('.', ',')} mil`
    : String(n);
const escapar = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const nomeArquivoSeguro = String(cliente.nome_cliente).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9 _-]/g, '').trim();
const viewsDiarias = Array.isArray(cliente.views_diarias_custom) ? cliente.views_diarias_custom : [];
const alcanceDiario = Array.isArray(cliente.alcance_diario_custom) ? cliente.alcance_diario_custom : [];
const viewsTotal = numero(cliente.views_total);
const alcanceTotal = numero(cliente.alcance_total);
const interacoesTotal = numero(cliente.interacoes_total);
const cliquesTotal = numero(cliente.cliques_total);
const seguidoresAtuais = numero(cliente.seguidores_atuais);
const seguidoresGanhos = numero(cliente.seguidores_ganhos);
const seguidoresPerdidos = numero(cliente.seguidores_perdidos);
const seguidoresLiquidos = numero(cliente.saldo_liquido);
const formatarExato = (n) => new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 0 }).format(n);
const formatarSaldoExato = (n) => n > 0 ? `+${formatarExato(n)}` : formatarExato(n);
const formatarPerdaExata = (n) => n > 0 ? `-${formatarExato(n)}` : '0';
const notaAlcance = cliente.alcance_limitado_30_dias
  ? `Alcance total: ${cliente.alcance_periodo} (limite máximo de 30 dias da API da Meta).`
  : '';

const grafico = (dados, cor, preenchimento) => {
  if (!dados.length) return '<div class="sem-dados">Série diária indisponível para esta métrica.</div>';
  const width = 760, height = 210, left = 18, top = 12, bottom = 30;
  const max = Math.max(...dados.map((d) => d.value), 1);
  const x = (i) => left + (i * (width - left * 2)) / Math.max(dados.length - 1, 1);
  const y = (v) => top + (height - top - bottom) * (1 - v / max);
  const pontos = dados.map((d, i) => `${x(i).toFixed(1)},${y(d.value).toFixed(1)}`).join(' ');
  const area = `${left},${height - bottom} ${pontos} ${width - left},${height - bottom}`;
  const passos = Math.max(1, Math.ceil(dados.length / 6));
  const labels = dados.map((d, i) => i % passos === 0 || i === dados.length - 1
    ? `<text x="${x(i)}" y="${height - 7}" text-anchor="middle" font-size="11" fill="#7181a2">${d.label}</text>` : '').join('');
  const grids = [0, .25, .5, .75, 1].map((p) => `<line x1="${left}" x2="${width-left}" y1="${top + p * (height-top-bottom)}" y2="${top + p * (height-top-bottom)}" stroke="#e2eaf5" stroke-width="1"/>`).join('');
  return `<svg viewBox="0 0 ${width} ${height}" xmlns="http://www.w3.org/2000/svg">${grids}<polygon points="${area}" fill="${preenchimento}"/><polyline points="${pontos}" fill="none" stroke="${cor}" stroke-width="4" stroke-linejoin="round" stroke-linecap="round"/>${labels}</svg>`;
};

