.total strong { display:block; color:#173765; font-size:38px; margin-top:10px; }
.grafico { width:100%; min-height:210px; }
.grafico svg { width:100%; height:210px; display:block; }
.sem-dados { height:190px; display:flex; align-items:center; justify-content:center; color:#7181a2; background:#f8faff; border-radius:10px; }
.rodape { margin-top:18px; text-align:center; color:#8290aa; font-size:10px; }
</style></head><body><main class="pagina">
<header class="header"><img class="logo" src="https://lememarketingmedico.com.br/wp-content/uploads/2025/09/Logo-Leme-Horizontal-Completa-scaled.png"><div class="titulo"><h1>Relatório de Desempenho</h1><div class="periodo">${escapar(cliente.periodo)}</div><div class="cliente">${escapar(cliente.nome_cliente)}</div></div></header>
<section class="kpis">
<div class="kpi"><small>Visualizações Instagram</small><strong>${formatar(viewsTotal)}</strong></div>
<div class="kpi"><small>Alcance</small><strong>${formatar(alcanceTotal)}</strong></div>
<div class="kpi"><small>Interações</small><strong>${formatar(interacoesTotal)}</strong></div>
<div class="kpi"><small>Cliques no link</small><strong>${formatar(cliquesTotal)}</strong></div>
</section>
<section class="seguidores"><h2>Movimentação de seguidores</h2><div class="seguidores-grid">
<div class="seguidor"><small>Seguidores atuais</small><strong>${formatarExato(seguidoresAtuais)}</strong></div>
<div class="seguidor ganhos"><small>Ganhos no período</small><strong>+${formatarExato(seguidoresGanhos)}</strong></div>
<div class="seguidor perdas"><small>Perdas no período</small><strong>${formatarPerdaExata(seguidoresPerdidos)}</strong></div>
<div class="seguidor liquido"><small>Saldo líquido</small><strong>${formatarSaldoExato(seguidoresLiquidos)}</strong></div>
</div></section>
<section class="secao"><h2>Evolução diária de visualizações</h2><div class="linha"><div class="total"><small>Total de visualizações</small><strong>${formatar(viewsTotal)}</strong></div><div class="grafico">${grafico(viewsDiarias,'#4a90d9','rgba(74,144,217,.15)')}</div></div></section>
<section class="secao"><h2>Evolução diária de alcance</h2><div class="linha"><div class="total"><small>Total de alcance</small><strong>${formatar(alcanceTotal)}</strong></div><div class="grafico">${grafico(alcanceDiario,'#173765','rgba(23,55,101,.12)')}</div></div></section>
<div class="rodape">${notaAlcance ? escapar(notaAlcance) + '<br>' : ''}Relatório automático gerado em ${new Date().toLocaleDateString('pt-BR')} • Instagram @${escapar(cliente.instagram_username)}</div>
</main></body></html>`;

return [{ json: {
  html,
  nome_arquivo: `Relatorio - ${nomeArquivoSeguro} - ${cliente.mes_arquivo}.pdf`,
  nome_cliente: cliente.nome_cliente,
  mes_arquivo: cliente.mes_arquivo,
  folder_mes_id: cliente.folder_mes_id,
  resumo: { viewsTotal, alcanceTotal, interacoesTotal, cliquesTotal, seguidoresAtuais, seguidoresGanhos, seguidoresPerdidos, seguidoresLiquidos }
}, pairedItem: { item: 0 } }];

const dados = $input.first().json;
const erros = [];
const esperado = Number(dados.dias_esperados);

if (dados.views_total_valido !== true || !Number.isFinite(Number(dados.views_total))) erros.push('visualizações totais');
if (dados.views_diarias_validas !== true || !Array.isArray(dados.views_diarias_custom) || dados.views_diarias_custom.length !== esperado) erros.push('visualizações diárias');
if (Number(dados.views_total) !== Number(dados.views_total_soma_dias)) erros.push('conferência entre visualizações totais e diárias');
if (dados.alcance_total_valido !== true || !Number.isFinite(Number(dados.alcance_total))) erros.push('alcance total');
if (dados.alcance_diario_valido !== true || !Array.isArray(dados.alcance_diario_custom) || dados.alcance_diario_custom.length !== esperado) erros.push('alcance diário');
if (dados.interacoes_total_valido !== true || !Number.isFinite(Number(dados.interacoes_total))) erros.push('interações');
if (dados.historico_completo !== true || !Number.isFinite(Number(dados.saldo_seguidores)) || dados.dias_encontrados !== dados.dias_esperados) erros.push('histórico de seguidores');
if (dados.metricas_seguidores_validas !== true || ![dados.seguidores_atuais, dados.seguidores_ganhos, dados.seguidores_perdidos, dados.saldo_liquido].every((v) => Number.isFinite(Number(v)))) erros.push('ganhos e perdas de seguidores');
if (Number(dados.saldo_liquido) !== Number(dados.seguidores_ganhos) - Number(dados.seguidores_perdidos)) erros.push('saldo líquido de seguidores');
if (Number(dados.seguidores_ganhos) !== Number(dados.saldo_seguidores)) erros.push('conferência dos seguidores ganhos');
if (dados.cliques_total_valido !== true || !Number.isFinite(Number(dados.cliques_total))) erros.push('cliques no link');

if (erros.length) {
  throw new Error(`Relatório de ${dados.nome_cliente} não foi gerado: dados inválidos em ${erros.join(', ')}. Nenhum PDF foi enviado.`);
}

return [{ json: dados }];

const blocos = $('Preparar blocos seguidores Meta').all();
const respostas = $input.all();
const base = { ...blocos[0].json };
delete base.meta_since;
delete base.meta_until;
delete base.meta_since_date;
delete base.meta_until_date;

const normalizar = (valor) => String(valor ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toUpperCase()
  .replace(/[^A-Z0-9]+/g, '_');

let ganhos = 0;
let perdas = 0;
let blocosValidos = 0;

for (const resposta of respostas) {
  const metrica = (resposta.json.data ?? []).find((d) => d.name === 'follows_and_unfollows');
  const breakdowns = metrica?.total_value?.breakdowns;
  if (!Array.isArray(breakdowns)) continue;

  const resultados = breakdowns.flatMap((grupo) =>
    Array.isArray(grupo.results) ? grupo.results : []
  );
  let reconhecidos = 0;

  for (const resultado of resultados) {
    const valor = Number(resultado.value);
    if (!Number.isFinite(valor)) continue;
    const dimensoes = (resultado.dimension_values ?? []).map(normalizar);
    const perda = dimensoes.some((v) => v === 'NON_FOLLOWER' || v.includes('UNFOLLOW'));
    const ganho = dimensoes.some((v) => v === 'FOLLOWER' || v === 'FOLLOW' || v.includes('NEW_FOLLOW'));

    if (perda) {
      perdas += Math.abs(valor);
      reconhecidos++;
    } else if (ganho) {
      ganhos += Math.abs(valor);
      reconhecidos++;
    }
  }

  if (!resultados.length || reconhecidos === resultados.length) blocosValidos++;
}

ganhos = Math.trunc(ganhos);
perdas = Math.trunc(perdas);
const ganhosHistorico = Number(base.saldo_seguidores);
const seguidoresAtuais = Number(base.seguidores_atuais);
let aviso = null;
let valido = respostas.length === blocos.length && blocosValidos === blocos.length;

if (![ganhos, perdas, ganhosHistorico, seguidoresAtuais].every(Number.isFinite)) {
  valido = false;
  aviso = `Cliente ignorado: os dados de seguidores de ${base.nome_cliente} contêm valores inválidos.`;
} else if (!valido) {
  aviso = `Cliente ignorado: a Meta não devolveu ganhos e perdas completos para ${base.nome_cliente}.`;
} else if (ganhos !== ganhosHistorico) {
  valido = false;
  aviso = `Cliente ignorado: a Meta retornou ${ganhos} seguidores ganhos para ${base.nome_cliente}, mas o histórico diário validado soma ${ganhosHistorico}.`;
}

return [{ json: {
  ...base,
  metricas_seguidores_validas: valido,
  seguidores_atuais: seguidoresAtuais,
  seguidores_ganhos: ganhos,
  seguidores_perdidos: perdas,
  saldo_liquido: ganhos - perdas,
  ganhos_historico: ganhosHistorico,
  aviso,
} }];

return [{ json: {
  status: 'IGNORADO_DADOS_INCOMPLETOS',
  cliente: $json.nome_cliente || $json.cliente_nome,
  instagram_id: $json.instagram_id,
  aviso: $json.aviso || 'Dados obrigatórios incompletos; nenhum PDF foi enviado.',
  dias_faltantes: $json.dias_faltantes ?? [],
}}];

const base = $input.first().json;
const inicio = new Date(`${base.since_date}T00:00:00.000Z`);
const fim = new Date(`${base.until_date}T00:00:00.000Z`);
const esperado = Math.round((fim.getTime() - inicio.getTime()) / 86400000);
const porData = new Map();

for (const linha of Array.isArray(base.historico_seguidores) ? base.historico_seguidores : []) {
  if (String(linha.instagram_id ?? '') !== String(base.instagram_id)) continue;
  const data = String(linha.data ?? '').slice(0, 10);
  if (data < base.since_date || data >= base.until_date) continue;
  const valor = Number(linha.saldo_dia);
  if (!Number.isFinite(valor)) throw new Error(`Saldo de seguidores inválido em ${data} para ${base.nome_cliente}.`);
  porData.set(data, valor);
}

const faltantes = [];
for (let t = inicio.getTime(); t < fim.getTime(); t += 86400000) {
  const data = new Date(t).toISOString().slice(0, 10);
  if (!porData.has(data)) faltantes.push(data);
}

return [{ json: {
  ...base,
  historico_completo: faltantes.length === 0,
  saldo_seguidores: faltantes.length ? null : [...porData.values()].reduce((soma, valor) => soma + valor, 0),
  dias_encontrados: porData.size,
  dias_esperados: esperado,
  dias_faltantes: faltantes,
  aviso: faltantes.length ? `Cliente ignorado: histórico de seguidores incompleto para ${base.nome_cliente} (${porData.size}/${esperado} dias). Nenhum PDF foi enviado.` : null,
}}];

const dias = $('Preparar dias de visualizações').all();
const respostas = $input.all();
if (!dias.length || respostas.length !== dias.length) {
  throw new Error('A quantidade de respostas diárias de visualizações está incompleta.');
}

let metricasEncontradas = 0;
const viewsDiarias = dias.map((dia, index) => {
  const metrica = (respostas[index]?.json?.data ?? []).find((d) => d.name === 'views');
  const valor = Number(metrica?.total_value?.value);
  if (Number.isFinite(valor)) metricasEncontradas++;
  return { label: dia.json.dia_label, value: Number.isFinite(valor) ? valor : 0 };
});

const base = { ...dias[0].json };
delete base.dia_since;
delete base.dia_until;
delete base.dia_label;
return [{ json: {
  ...base,
  views_diarias_custom: viewsDiarias,
  views_diarias_validas: metricasEncontradas === dias.length,
  views_total_soma_dias: viewsDiarias.reduce((soma, dia) => soma + dia.value, 0),
}}];

const base = $input.first().json;
const inicio = new Date(`${base.since_date}T00:00:00.000Z`);
const fim = new Date(`${base.until_date}T00:00:00.000Z`);
const itens = [];

for (let data = new Date(inicio); data < fim; data = new Date(data.getTime() + 86400000)) {
  const proximo = new Date(data.getTime() + 86400000);
  const diaIso = data.toISOString().slice(0, 10);
  itens.push({ json: {
    ...base,
    dia_since: Math.floor(data.getTime() / 1000),
    dia_until: Math.floor((proximo.getTime() - 1000) / 1000),
    dia_label: `${diaIso.slice(8, 10)}/${diaIso.slice(5, 7)}`,
  }});
}
if (!itens.length) throw new Error(`Nenhum dia preparado para ${base.nome_cliente}.`);
return itens;

const clientes = $('Normalizar clientes seguros').first().json.clientes ?? [];
const owned = $('Listar paginas proprias1').first().json.data ?? [];
const shared = $('Listar paginas dos clientes1').first().json.data ?? [];
const config = $('Configuração').first().json;
const historicoCompleto = $('Ler todos os seguidores').all()
  .map((item) => item.json ?? {})
  .filter((linha) => linha.instagram_id && linha.data);

const normalizar = (v) => String(v ?? '').trim().replace(/^@/, '').toLowerCase();
const contas = [...owned.map((p) => ({ ...p, origem: 'LEME' })), ...shared.map((p) => ({ ...p, origem: 'CLIENTE' }))]
  .filter((p) => p.instagram_business_account?.id)
  .map((p) => ({
    origem: p.origem,
    page_id: String(p.id ?? ''),
    page_name: p.name,
    instagram_id: String(p.instagram_business_account.id),
    instagram_username: normalizar(p.instagram_business_account.username),
    instagram_name: p.instagram_business_account.name ?? p.name,
    seguidores_atuais: p.instagram_business_account.followers_count ?? null,
    quantidade_midias: p.instagram_business_account.media_count ?? null,
  }));

const porUsuario = new Map(contas.map((c) => [c.instagram_username, c]));
const porId = new Map();
for (const conta of contas) {
  porId.set(String(conta.instagram_id), conta);
  porId.set(String(conta.page_id), conta);
}

const encontrados = [];
const naoEncontrados = [];
const contasUsadas = new Map();
const historicoPorInstagram = new Map();
for (const linha of historicoCompleto) {
  const chave = String(linha.instagram_id);
  if (!historicoPorInstagram.has(chave)) historicoPorInstagram.set(chave, []);
  historicoPorInstagram.get(chave).push(linha);
}

for (const cliente of clientes) {
  const porNome = porUsuario.get(normalizar(cliente.usuario_instagram));
  const porAsset = porId.get(String(cliente.instagram_asset_id || ''));

  if (porNome && porAsset && String(porNome.instagram_id) !== String(porAsset.instagram_id)) {
    naoEncontrados.push({
      nome: cliente.nome_cliente,
      instagram: cliente.usuario_instagram,
      motivo: 'usuário e asset_id apontam para contas diferentes',
    });
    continue;
  }

  const conta = porNome ?? porAsset;
  if (!conta) {
    naoEncontrados.push({
      nome: cliente.nome_cliente,
      instagram: cliente.usuario_instagram,
      motivo: 'conta não autorizada no portfólio LEME',
    });
    continue;
  }

  const jaUsadaPor = contasUsadas.get(String(conta.instagram_id));
  if (jaUsadaPor) {
    naoEncontrados.push({
      nome: cliente.nome_cliente,
      instagram: cliente.usuario_instagram,
      motivo: `conta já vinculada a ${jaUsadaPor}`,
    });
    continue;
  }

  contasUsadas.set(String(conta.instagram_id), cliente.nome_cliente);
  encontrados.push({
    ...cliente,
    ...conta,
    since: config.since,
    until: config.until,
    since_date: config.since_date,
    until_date: config.until_date,
    periodo: config.periodo,
    ano: config.ano,
    mes_pasta: config.mes_pasta,
    mes_arquivo: config.mes_arquivo,
    historico_seguidores: historicoPorInstagram.get(String(conta.instagram_id)) ?? [],
  });
}

if (!encontrados.length) {
  throw new Error(`Nenhum cliente do Sistema LEME foi localizado entre as contas Meta autorizadas. Não encontrados: ${naoEncontrados.map((c) => '@' + c.instagram).join(', ')}`);
}

return encontrados.map((json) => ({
  json: { ...json, clientes_nao_encontrados: naoEncontrados },
}));

const body = $input.first().json ?? {};
const clientesBrutos = Array.isArray(body.clientes)
  ? body.clientes
  : Array.isArray(body.data?.clientes)
    ? body.data.clientes
    : [];

const texto = (v) => String(v ?? '').trim();
const usuario = (v) => texto(v)
  .replace(/^https?:\/\/(www\.)?instagram\.com\//i, '')
  .replace(/^@/, '')
  .replace(/[/?#].*$/, '')
  .toLowerCase();
const pasta = (v) => {
  const s = texto(v);
  const match = s.match(/\/folders\/([a-zA-Z0-9_-]+)/);
  return match?.[1] ?? s;
};
const assetId = (...valores) => {
  for (const valor of valores) {
    const s = texto(valor);
    const query = s.match(/[?&]asset_id=([0-9]+)/i)?.[1];
    if (query) return query;
    if (/^\d{8,}$/.test(s)) return s;
  }
  return '';
};

const clientes = clientesBrutos
  .filter((c) => texto(c.status).toLowerCase() === 'ativo')
  .map((c) => ({
    cliente_id: texto(c.id || c.registro_id),
    nome_cliente: texto(c.nome_cliente || c.nome || c.cliente),
    usuario_instagram: usuario(
      c.usuario_instagram || c.conta_instagram || c.instagram || c.instagram_login
    ),
    instagram_asset_id: assetId(
      c.instagram_asset_id,
      c.instagram_business_id,
      c.meta_instagram_id,
      c.link_relatorio
    ),
    drive_folder_id: pasta(c.drive_folder_id || c.banco_google || c.drive_folder_url),
  }))
  .filter((c) => c.nome_cliente && (c.instagram_asset_id || c.usuario_instagram) && c.drive_folder_id);

if (!clientes.length) {
  throw new Error('O Sistema LEME não retornou clientes ativos com nome, Instagram e pasta do Drive.');
}

return [{ json: { clientes, quantidade: clientes.length } }];

const now = new Date();
const inicio = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
const fimExclusivo = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
const fim = new Date(fimExclusivo.getTime() - 1000);
const diasPeriodo = Math.round((fimExclusivo.getTime() - inicio.getTime()) / 86400000);
const nomesMeses = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
];
const ddmm = (d) => `${String(d.getUTCDate()).padStart(2, '0')}/${String(d.getUTCMonth() + 1).padStart(2, '0')}`;
const iso = (d) => d.toISOString().slice(0, 10);

return [{
  json: {
    graph_version: 'v25.0',
    business_id: '799154829958463',
    sistema_url: 'https://sistema.lememarketingmedico.com.br/api/sync',
    leme_system_url: 'https://sistema.lememarketingmedico.com.br',
    n8n_leme_secret: 'COLE_AQUI_O_MESMO_N8N_LEME_SECRET_DO_BACKEND',
    whatsapp_destino: '120363044858833254@g.us',
    since: Math.floor(inicio.getTime() / 1000),
    until: Math.floor(fim.getTime() / 1000),
    since_date: iso(inicio),
    until_date: iso(fimExclusivo),
    dias_periodo: diasPeriodo,
    periodo: `${ddmm(inicio)} a ${ddmm(fim)}/${fim.getUTCFullYear()}`,
    ano: fim.getUTCFullYear(),
    mes: String(fim.getUTCMonth() + 1).padStart(2, '0'),
    mes_nome: nomesMeses[fim.getUTCMonth()],
    mes_pasta: `${String(fim.getUTCMonth() + 1).padStart(2, '0')} - ${nomesMeses[fim.getUTCMonth()]}`,
    mes_arquivo: `${String(fim.getUTCMonth() + 1).padStart(2, '0')}-${fim.getUTCFullYear()}`,
  }
}];
